/**
 * Peluncur adaLOCAL untuk Banana Slides.
 *
 * App ini DUA proses: backend (AI + basis data) dan tampilan yang meneruskan
 * panggilan `/api` ke backend. Pemasang adaLOCAL mengawasi SATU proses, jadi
 * berkas ini yang menyatukannya: menyalakan keduanya, meneruskan seluruh
 * keluaran apa adanya, dan MATI begitu salah satunya mati.
 *
 * Ia juga yang menentukan KAPAN app boleh disebut siap. Ini bukan hal sepele:
 * tampilan menyala dalam setengah detik sedangkan backend butuh belasan detik,
 * jadi kalau penanda siap diambil dari tampilan saja, pelanggan membuka app
 * tepat pada saat setiap panggilan masih menjawab 500 - dan menyimpulkan
 * app-nya rusak. Terbukti di uji lokal 21 Agu: 15 detik pertama sesudah
 * "siap" seluruhnya HTTP 500. Karena itu baris siap di bawah baru dicetak
 * setelah backend DAN tampilan sama-sama menjawab.
 */
const { spawn } = require('child_process');
const path = require('path');
const http = require('http');

const akar = __dirname;
const portBackend = process.env.BACKEND_PORT || '42021';
const portTampilan = process.env.FRONTEND_PORT || '42022';
const anak = [];
let sedangTutup = false;

function nyalakan(nama, perintah, argumen, cwd) {
  // shell:true wajib di Windows: `npm` di sana adalah `npm.cmd`.
  const p = spawn(perintah, argumen, { cwd, shell: true, env: process.env });
  p.stdout.on('data', (d) => process.stdout.write(d));
  p.stderr.on('data', (d) => process.stdout.write(d));
  p.on('exit', (kode) => {
    if (sedangTutup) return;
    console.log(`[adaLOCAL] ${nama} berhenti (kode ${kode}) - menutup sisanya.`);
    tutup(kode === 0 ? 1 : kode || 1);
  });
  anak.push(p);
  return p;
}

function tutup(kode) {
  if (sedangTutup) return;
  sedangTutup = true;
  for (const p of anak) {
    try { p.kill(); } catch { /* sudah mati */ }
  }
  setTimeout(() => process.exit(kode), 500);
}

function cek(port, jalur) {
  return new Promise((selesai) => {
    const permintaan = http.get(
      { host: '127.0.0.1', port: Number(port), path: jalur, timeout: 3000 },
      (r) => { r.resume(); selesai(r.statusCode > 0 && r.statusCode < 500); }
    );
    permintaan.on('error', () => selesai(false));
    permintaan.on('timeout', () => { permintaan.destroy(); selesai(false); });
  });
}

async function tungguSiap() {
  // Batas 6 menit: pemasang punya batasnya sendiri, ini cuma penjaga supaya
  // proses ini tak menunggu selamanya kalau backend gagal diam-diam.
  for (let i = 0; i < 120; i++) {
    if (sedangTutup) return;
    const [backendSiap, tampilanSiap] = await Promise.all([
      cek(portBackend, '/health'),
      cek(portTampilan, '/'),
    ]);
    if (backendSiap && tampilanSiap) {
      console.log(`[adaLOCAL] SIAP DIPAKAI di http://127.0.0.1:${portTampilan}`);
      return;
    }
    await new Promise((r) => setTimeout(r, 3000));
  }
  console.log('[adaLOCAL] backend belum menjawab sesudah 6 menit - lihat baris galat di atas.');
}

process.on('SIGINT', () => tutup(0));
process.on('SIGTERM', () => tutup(0));

// Backend dulu: tampilan yang menyala lebih dulu hanya memperlihatkan galat
// proxy sampai backend siap, dan itu terlihat seperti app rusak.
nyalakan('backend', 'python', ['app.py'], path.join(akar, 'backend'));
nyalakan('tampilan', 'npm', ['run', 'dev'], path.join(akar, 'frontend'));
tungguSiap();
